import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import Google from "next-auth/providers/google";
import { findOrCreateOAuthUser, verifyPassword } from "@/lib/users";

export const { handlers, signIn, signOut, auth } = NextAuth({
  providers: [
    Google({
      clientId: process.env.AUTH_GOOGLE_ID,
      clientSecret: process.env.AUTH_GOOGLE_SECRET,
    }),
    Credentials({
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        if (typeof credentials?.email !== "string" || typeof credentials?.password !== "string") {
          return null;
        }
        const user = await verifyPassword(credentials.email, credentials.password);
        return user ?? null;
      },
    }),
  ],
  session: { strategy: "jwt" },
  pages: { signIn: "/sign-in" },
  callbacks: {
    // Provision (or link to) a local user record the first time someone
    // signs in with Google, so the rest of the app only ever deals with
    // src/lib/users.ts's own User type.
    async signIn({ user, account }) {
      if (account?.provider === "google") {
        if (!user.email) return false;
        await findOrCreateOAuthUser({ email: user.email, name: user.name ?? user.email });
      }
      return true;
    },
  },
});

